import threading
import time

def descargar(nombre, segundos):
    print(f"inicia {nombre}")
    time.sleep(segundos)
    print(f"fin {nombre}")

inicio = time.perf_counter()
hilos = [
    threading.Thread(target=descargar, args=(f"archivo{i}", 1))
    for i in (1, 2)
]
for hilo in hilos:
    hilo.start()
for hilo in hilos:
    hilo.join()

print(f"total: {time.perf_counter() - inicio:.1f} s")

from multiprocessing import Pool

def cuadrado(n):
    return n * n

if __name__ == "__main__":
    with Pool() as pool:
        print(pool.map(cuadrado, range(6)))
